  /**
   * Description
   */
  description: string;
  /**
   * Groups
   */
  groups: Array<RequirementGroup>;
  /**
   * Name
   */
  name: string;
  /**
   * Notes
   *
   * The list's footnotes, in order.
   */
  notes: Array<string>;
